rification)', 'cases': [{'input': [{'parameter': 'key', 'value': 'new TSIG("hmac-md5", "secret".getBytes())'}, {'parameter': 'error', 'value': 'Rcode.NOERROR'}, {'parameter': 'querytsig', 'value': 'new TSIGRecord(Name.fromString("example.com."), DClass.IN, 300, key, new byte[0])'}], 'expected': 'Message.tsigState == Message.TSIG_VERIFIED && Message.isVerified() == true', 'description': 'When a query TSIGRecord is supplied and the MAC verification succeeds, the method should set the state to TSIG_VERIFIED and isVerified() must return true.'}]}, {'group': 'Verification with query TSIG (failed verification)', 'cases': [{'input': [{'parameter': 'key', 'value': 'new TSIG("hmac-md5", "secret".getBytes())'}, {'parameter': 'error', 'value': 'Rcode.NOERROR'}, {'parameter': 'querytsig', 'value': 'new TSIGRecord(Name.fromString("example.com."), DClass.IN, 300, new TSIG("hmac-md5", "wrong".getBytes()), new byte[0])'}], 'expected': 'Message.tsigState == Message.TSIG_FAILED && Message.isVerified() == false', 'description': 'If the supplied query TSIGRecord does not match the key (MAC verification fails), the method must transition to TSIG_FAILED and verification flag stays false.'}]}, {'group': 'Intermediate state handling (TSIG_INTERMEDIATE)', 'cases': [{'input': [{'parameter': 'key', 'value': 'new TSIG("hmac-md5", "secret".getBytes())'}, {'parameter': 'error', 'value': 'Rcode.NOERROR'}, {'parameter': 'querytsig', 'value': 'null'}], 'expected': 'Message.tsigState == Message.TSIG_INTERMEDIATE && Message.isSigned() == false', 'description': 'If the method is called during message construction (no query TSIG and no error), it should place the TSIG in an intermediate state awaiting final signing.'}]}]
